package com.tutorhub.parent.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="children") public class Child { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="parent_id") private ParentProfile parent; private String name; private short grade; private String school; private String notes; @Column(name="created_at") private Instant createdAt; @PrePersist void init(){createdAt=Instant.now();} public Long getId(){return id;} public String getName(){return name;} public short getGrade(){return grade;} public String getSchool(){return school;} public String getNotes(){return notes;} public ParentProfile getParent(){return parent;} public void setParent(ParentProfile x){parent=x;} public void setName(String x){name=x;} public void setGrade(short x){grade=x;} public void setSchool(String x){school=x;} public void setNotes(String x){notes=x;} }
